-- Accountable SLA/follow-up metadata for client support workflows.
alter table public.client_support_requests add column if not exists response_due_at timestamptz,add column if not exists first_responded_at timestamptz,add column if not exists escalated_at timestamptz,add column if not exists escalation_reason text;
create or replace function public.set_client_support_sla() returns trigger language plpgsql set search_path=public,pg_temp as $$ begin if new.response_due_at is null then new.response_due_at:=new.created_at+(case when new.priority='URGENT' then interval '1 hour' when new.priority='HIGH' then interval '4 hours' else interval '24 hours' end);end if;return new;end$$;
drop trigger if exists client_support_sla on public.client_support_requests;
create trigger client_support_sla before insert on public.client_support_requests for each row execute function public.set_client_support_sla();
create or replace function public.escalate_overdue_client_support_requests() returns integer language plpgsql security definer set search_path=public,pg_temp as $$ declare n integer;begin update public.client_support_requests set escalated_at=coalesce(escalated_at,now()),escalation_reason=coalesce(escalation_reason,'Response SLA exceeded'),updated_at=now() where status not in ('RESOLVED','CLOSED') and response_due_at<now() and escalated_at is null;get diagnostics n=row_count;insert into public.audit_log(action,entity_type,entity_id,after_state,reason) select 'CLIENT_SUPPORT_REQUEST_ESCALATED','client_support_request',r.id::text,jsonb_build_object('status',r.status,'response_due_at',r.response_due_at,'escalated_at',r.escalated_at),'Support response SLA exceeded' from public.client_support_requests r where r.escalated_at>=now()-interval '5 seconds' and r.escalation_reason='Response SLA exceeded';return n;end$$;
revoke execute on function public.escalate_overdue_client_support_requests() from public,anon,authenticated;
grant execute on function public.escalate_overdue_client_support_requests() to service_role;
